mapper.select:
select

    /*+ INDEX(a idx_oa_process_user_create_time) */


from oa_process a



        and (a.process_code like CONCAT('%',#{vo.keyword},'%') or
            a.title like CONCAT('%',#{vo.keyword},'%'))


        and a.user_id = #{vo.userId}


        and a.status = #{vo.status}


        and a.create_time >= #{vo.createTimeBegin}


        and a.create_time <= #{vo.createTimeEnd}



order by a.create_time desc, a.id desc

select distinct
from oa_process_cc g join oa_process a on a.id = g.process_id
where g.user_id = #{userId} and g.is_deleted = 0 and a.is_deleted = 0 order by a.create_time desc, a.id desc limit #{limit} offset #{offset}
